    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint beforeOther = c.getBalance(other); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterSender = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterOther = c.getBalance(other); if (__ESBMC_reverted()) return;
        assert(address(c).balance >= afterSender + afterOther && afterOther == beforeOther);
    }

    receive() external payable {}
}

