// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address other, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeOther;
        try c.getBalance(other) returns (uint256 __r) { beforeOther = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterSender;
        try c.getBalance(address(this)) returns (uint256 __r) { afterSender = __r; } catch { return; }
        uint256 afterOther;
        try c.getBalance(other) returns (uint256 __r) { afterOther = __r; } catch { return; }
        assertTrue(address(c).balance >= afterSender + afterOther && afterOther == beforeOther);
    }

    function testFuzz_run(address other, uint256 amount) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(other, amount);
    }

    receive() external payable {}
}
